#include <stdio.h>
#include <string.h>

#define MAX_N 100
#define MAX_W 100000

long long dp[MAX_W + 1];

int main() {
    int N, W;
    scanf("%d %d", &N, &W);

    // Initialize dp array
    memset(dp, 0, sizeof(dp));

    for (int i = 0; i < N; i++) {
        int w, v;
        scanf("%d %d", &w, &v);

        // Iterate from W down to w to avoid reusing the same item
        for (int j = W; j >= w; j--) {
            if (dp[j - w] + v > dp[j]) {
                dp[j] = dp[j - w] + v;
            }
        }
    }

    // Find the maximum value achievable
    long long max_value = 0;
    for (int j = 0; j <= W; j++) {
        if (dp[j] > max_value) {
            max_value = dp[j];
        }
    }

    printf("%lld\n", max_value);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

int main(void) {
    int N;
    ll W;
    if (scanf("%d %lld", &N, &W) != 2) return 0;

    ll *dp = (ll *)calloc(W + 1, sizeof(ll));
    if (!dp) return 0;

    for (int i = 0; i < N; i++) {
        ll w, v;
        scanf("%lld %lld", &w, &v);

        for (ll cur = W; cur >= w; cur--) {
            ll candidate = dp[cur - w] + v;
            if (candidate > dp[cur]) dp[cur] = candidate;
        }
    }

    ll ans = 0;
    for (ll i = 0; i <= W; i++) {
        if (dp[i] > ans) ans = dp[i];
    }

    printf("%lld\n", ans);

    free(dp);
    return 0;
}

