import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int N = fs.nextInt();
        long W = fs.nextLong();

        long[] dp = new long[(int) W + 1];

        for (int i = 0; i < N; i++) {
            int w = fs.nextInt();
            long v = fs.nextLong();

            for (int weight = (int) W; weight >= w; weight--) {
                dp[weight] = Math.max(dp[weight], dp[weight - w] + v);
            }
        }

        long ans = 0;
        for (int weight = 0; weight <= W; weight++) {
            ans = Math.max(ans, dp[weight]);
        }

        System.out.println(ans);
    }
}

import sys

def main():
    input = sys.stdin.readline
    N, W = map(int, input().split())
    items = [tuple(map(int, input().split())) for _ in range(N)]

    # Standard 0/1 knapsack DP by weight:
    # dp[x] = maximum value achievable with total weight exactly/at most x
    dp = [0] * (W + 1)

    for w, v in items:
        for weight in range(W, w - 1, -1):
            candidate = dp[weight - w] + v
            if candidate > dp[weight]:
                dp[weight] = candidate

    print(max(dp))

